  1→/**
  2→ * run-unity-pipeline.ts — Unity 多态三段管线串联入口（WT-044）
  3→ *
  4→ * 串起三段（DR-44）：
  5→ *   1. explore LLM  (explore-service.ts --source unity) → findings.json + verdict.json
  6→ *   2. narrative LLM (narrative-service.ts --source unity) → narrative.json
  7→ *                  （detectStateMode 检测 base/cur 子目录 → 选 unity-multi-state.txt 模板）
  8→ *   3. render 纯代码 (render-html.ts --dir <output>) → report.html
  9→ *
 10→ * Usage (from repo root or web/):
 11→ *   npx tsx web/server/prism/run-unity-pipeline.ts --multi-state-dir <udiff_dir> [--out <dir>] [--skip-explore]
 12→ *
 13→ * --multi-state-dir: udiff 目录路径（含 base/ + cur/ 子目录，每个有 preprocess-result.json）
 14→ * --out: 输出目录（默认 web/data/prism-out/<udiff_id>/<timestamp>）
 15→ * --skip-explore: 跳过 explore 阶段（复用已有 findings.json/verdict.json），只跑 narrative + render。
 16→ *                 用于反复调 narrative/render 不重跑 explore。
 17→ *
 18→ * 注意：本脚本会实际调用 LLM（explore + narrative），耗时较长（explore ~10-20min, narrative ~5min）。
 19→ */
 20→
 21→import { runPrismExplore } from './explore-service.js';
 22→import { runPrismNarrative } from './narrative-service.js';
 23→import { registerBuiltinPipelines } from './report-pipeline.js';
 24→import { spawn } from 'node:child_process';
 25→import * as path from 'node:path';
 26→import * as fs from 'node:fs';
 27→import { fileURLToPath } from 'node:url';
 28→
 29→// ESM 兼容：__dirname 在 ESM 下未定义
 30→const __filename = fileURLToPath(import.meta.url);
 31→const __dirname = path.dirname(__filename);
 32→
 33→// ──────────────────────────────── CLI 参数 ────────────────────────────────
 34→
 35→const argv = process.argv.slice(2);
 36→function getFlag(flag: string): string | undefined {
 37→  const idx = argv.indexOf(flag);
 38→  return idx === -1 ? undefined : argv[idx + 1];
 39→}
 40→function hasFlag(flag: string): boolean {
 41→  return argv.includes(flag);
 42→}
 43→
 44→if (hasFlag('--help') || hasFlag('-h')) {
 45→  console.log(
 46→    'Usage: npx tsx web/server/prism/run-unity-pipeline.ts --multi-state-dir <udiff_dir> [--out <dir>] [--skip-explore] [--timeout-ms <ms>]\n' +
 47→    '\n' +
 48→    '  --multi-state-dir  udiff 目录路径（含 base/ + cur/ 子目录）\n' +
 49→    '  --out              Output directory (default: web/data/prism-out/<udiff_id>/<timestamp>)\n' +
 50→    '  --skip-explore     Skip explore stage (reuse existing findings.json/verdict.json)\n' +
 51→    '  --timeout-ms       Per-stage timeout in ms (default: 1200000 = 20 min for explore, 600000 = 10 min for narrative)\n',
 52→  );
 53→  process.exit(0);
 54→}
 55→
 56→const multiStateDirArg = getFlag('--multi-state-dir');
 57→const rawOutDir = getFlag('--out');
 58→const skipExplore = hasFlag('--skip-explore');
 59→const timeoutMs = getFlag('--timeout-ms') ? parseInt(getFlag('--timeout-ms')!, 10) : undefined;
 60→
 61→if (!multiStateDirArg && !skipExplore) {
 62→  console.error('[pipeline] --multi-state-dir is required (or use --skip-explore with --run-id)');
 63→  process.exit(1);
 64→}
 65→
 66→// 解析 udiff 目录：相对路径相对于 cwd（通常 web/），绝对路径直接用
 67→const multiStateDir = multiStateDirArg
 68→  ? (path.isAbsolute(multiStateDirArg) ? multiStateDirArg : path.resolve(process.cwd(), multiStateDirArg))
 69→  : undefined;
 70→
 71→// runId = udiff 目录名（如 udiff_1782983710451_be175ef1）
 72→const runId = multiStateDir ? path.basename(multiStateDir) : (getFlag('--run-id') ?? 'udiff_1782983710451_be175ef1');
 73→
 74→// WT-031 需求 C：--out 相对于 cwd 解析
 75→const outputDir = rawOutDir
 76→  ? (path.isAbsolute(rawOutDir) ? rawOutDir : path.resolve(process.cwd(), rawOutDir))
 77→  : undefined;
 78→
 79→// ──────────────────────────────── 主流程 ────────────────────────────────
 80→
 81→async function main(): Promise<void> {
 82→  // 注册内置 pipeline（unity + perfetto）
 83→  registerBuiltinPipelines();
 84→  console.log('[pipeline] Registered builtin pipelines: unity, perfetto');
 85→
 86→  const repoRoot = path.resolve(__dirname, '../../..');
 87→  let exploreOutputDir: string;  // explore 阶段的输出目录（findings.json/verdict.json 所在）
 88→  let narrativeOutputDir: string;  // narrative + render 阶段的输出目录（narrative.json/report.html 所在）
 89→
 90→  // ── 阶段 1：explore LLM ──
 91→  if (skipExplore) {
 92→    // 复用已有 findings.json/verdict.json：找最新的 run 目录
 93→    const runBaseDir = path.join(repoRoot, 'web', 'data', 'prism-out', runId);
 94→    if (!fs.existsSync(runBaseDir)) {
 95→      console.error(`[pipeline] --skip-explore but run dir not found: ${runBaseDir}`);
 96→      process.exit(1);
 97→    }
 98→    // 找含 findings.json 的最新时间戳子目录
 99→    const subdirs = fs.readdirSync(runBaseDir)
100→      .filter(d => fs.statSync(path.join(runBaseDir, d)).isDirectory())
101→      .filter(d => fs.existsSync(path.join(runBaseDir, d, 'findings.json')))
102→      .sort()
103→      .reverse();
104→    exploreOutputDir = subdirs.length > 0
105→      ? path.join(runBaseDir, subdirs[0])
106→      : runBaseDir;
107→    if (!fs.existsSync(path.join(exploreOutputDir, 'findings.json'))) {
108→      console.error(`[pipeline] --skip-explore but findings.json not found in: ${exploreOutputDir}`);
109→      process.exit(1);
110→    }
111→    console.log(`[pipeline] Stage 1 (explore): SKIPPED, reusing ${exploreOutputDir}`);
112→
113→    // --skip-explore 模式下支持 --out 新目录，不覆盖原报告
114→    if (outputDir) {
115→      narrativeOutputDir = path.isAbsolute(outputDir) ? outputDir : path.resolve(process.cwd(), outputDir);
116→      if (!fs.existsSync(narrativeOutputDir)) {
117→        fs.mkdirSync(narrativeOutputDir, { recursive: true });
118→        console.log(`[pipeline] Created new output dir: ${narrativeOutputDir}`);
119→      }
120→      // 复制 findings.json + verdict.json 到新目录（narrative-service 要读 findings.json）
121→      for (const fname of ['findings.json', 'verdict.json']) {
122→        const src = path.join(exploreOutputDir, fname);
123→        const dst = path.join(narrativeOutputDir, fname);
124→        if (fs.existsSync(src) && !fs.existsSync(dst)) {
125→          fs.copyFileSync(src, dst);
126→          console.log(`[pipeline] Copied ${fname} → ${narrativeOutputDir}`);
127→        }
128→      }
129→      console.log(`[pipeline] --skip-explore + --out: narrative/render will write to ${narrativeOutputDir} (original ${exploreOutputDir} untouched)`);
130→    } else {
131→      console.warn(`[pipeline] WARNING: --skip-explore without --out will overwrite existing narrative.json/report.html in ${exploreOutputDir}`);
132→      console.warn(`[pipeline] Suggestion: add --out data/prism-out/${runId}/<new-timestamp> to preserve original`);
133→      narrativeOutputDir = exploreOutputDir;
134→    }
135→  } else {
136→    console.log('[pipeline] Stage 1 (explore): starting...');
137→    const exploreResult = await runPrismExplore({
138→      source: 'unity',
139→      runId,
140→      outputDir,
141→      timeoutMs: timeoutMs ?? 20 * 60 * 1000,
142→    });
143→    if (!exploreResult.success) {
144→      console.error(`[pipeline] Stage 1 (explore) FAILED: ${exploreResult.error}`);
145→      process.exit(1);
146→    }
147→    exploreOutputDir = path.dirname(exploreResult.findingsPath);
148→    narrativeOutputDir = outputDir ? (path.isAbsolute(outputDir) ? outputDir : path.resolve(process.cwd(), outputDir)) : exploreOutputDir;
149→    console.log(`[pipeline] Stage 1 (explore): OK, ${exploreResult.findings.length} findings → ${exploreOutputDir}`);
150→  }
151→
152→  // ── 阶段 2：narrative LLM ──
153→  console.log('[pipeline] Stage 2 (narrative): starting...');
154→  const narrativeResult = await runPrismNarrative({
155→    source: 'unity',
156→    runId,
157→    outputDir: narrativeOutputDir,
158→    timeoutMs: timeoutMs ?? 10 * 60 * 1000,
159→  });
160→  if (!narrativeResult.success) {
161→    console.error(`[pipeline] Stage 2 (narrative) FAILED: ${narrativeResult.error}`);
162→    process.exit(1);
163→  }
164→  console.log(`[pipeline] Stage 2 (narrative): OK → ${narrativeResult.narrativePath}`);
165→
166→  // ── 阶段 3：render 纯代码 ──
167→  console.log('[pipeline] Stage 3 (render): starting...');
168→  const renderScript = path.join(__dirname, 'render-html.ts');
169→  const renderArgs = ['--import', 'tsx', renderScript, '--dir', narrativeOutputDir];
170→  const renderExitCode = await new Promise<number>((resolve) => {
171→    const child = spawn('node', renderArgs, {
172→      cwd: path.join(repoRoot, 'web'),
173→      stdio: 'inherit',
174→      shell: false,
175→    });
176→    child.on('close', resolve);
177→    child.on('error', (err) => {
178→      console.error(`[pipeline] Stage 3 (render) spawn error: ${err.message}`);
179→      resolve(1);
180→    });
181→  });
182→  if (renderExitCode !== 0) {
183→    console.error(`[pipeline] Stage 3 (render) FAILED: exit code ${renderExitCode}`);
184→    process.exit(1);
185→  }
186→  const reportHtmlPath = path.join(narrativeOutputDir, 'report.html');
187→  console.log(`[pipeline] Stage 3 (render): OK → ${reportHtmlPath}`);
188→
189→  console.log('\n════════════════════════════════════════');
190→  console.log('  Unity 多态三段管线 — 完成');
191→  console.log('════════════════════════════════════════');
192→  console.log(`  findings.json  : ${path.join(narrativeOutputDir, 'findings.json')}`);
193→  console.log(`  narrative.json : ${narrativeResult.narrativePath}`);
194→  console.log(`  report.html    : ${reportHtmlPath}`);
195→  console.log('════════════════════════════════════════');
196→}
197→
198→main().catch((err) => {
199→  console.error('[pipeline] Unexpected error:', err instanceof Error ? err.message : String(err));
200→  process.exit(1);
201→});
202→

